import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { MessageService } from 'primeng/api';
import { AdminAccountService } from '../../../../../../libs/openapi/src/api/admin-account.service';

@Component({
  selector: 'app-account-form',
  templateUrl: './account-form.component.html',
  styleUrls: ['./account-form.component.scss'],
  providers: [MessageService],
})
export class AccountFormComponent implements OnInit {
  accountForm: FormGroup;
  isEditMode = false;
  accountId: string | null = null;
  loading = false;

  constructor(
    private fb: FormBuilder,
    private route: ActivatedRoute,
    private router: Router,
    private accountService: AdminAccountService,
    private messageService: MessageService
  ) {
    this.accountForm = this.fb.group({
      name: ['', [Validators.required, Validators.minLength(2)]],
      account: ['', [Validators.required, Validators.minLength(3)]],
      email: ['', [Validators.required, Validators.email]],
      isActive: [true],
    });
  }

  ngOnInit(): void {
    this.accountId = this.route.snapshot.params['id'];
    if (this.accountId) {
      this.isEditMode = true;
      this.loadAccountData(this.accountId);
    }
  }

  loadAccountData(id: string) {
    this.loading = true;
    this.accountService.apiAdminAccountIdGet(id).subscribe({
      next: (response: any) => {
        this.accountForm.patchValue({
          name: response.data.name,
          email: response.data.email,
          account: response.data.account,
          isActive: response.data.isActive,
        });
        this.loading = false;
      },
      error: () => {
        this.messageService.add({
          severity: 'error',
          summary: 'Error',
          detail: '無法載入帳戶資料',
        });
        this.loading = false;
      },
    });
  }

  onSubmit() {
    if (this.accountForm.valid) {
      this.loading = true;
      const accountData = this.accountForm.value;

      const request =
        this.isEditMode && this.accountId
          ? this.accountService.apiAdminAccountIdPut(
              this.accountId,
              accountData
            )
          : this.accountService.apiAdminAccountPost(accountData);

      request.subscribe({
        next: () => {
          this.messageService.add({
            severity: 'success',
            summary: 'Success',
            detail: `Account ${
              this.isEditMode ? 'updated' : 'created'
            } successfully`,
          });
          this.router.navigate(['/accounts']);
        },
        error: () => {
          this.messageService.add({
            severity: 'error',
            summary: 'Error',
            detail: `Failed to ${
              this.isEditMode ? 'update' : 'create'
            } account`,
          });
          this.loading = false;
        },
      });
    }
  }
}
