import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { ConfirmationService, MessageService } from 'primeng/api';
import { AdminAccountService } from '../../../../../../libs/openapi/src/api/admin-account.service';

@Component({
  selector: 'app-account-list',
  templateUrl: './account-list.component.html',
  styleUrls: ['./account-list.component.scss'],
  providers: [MessageService, ConfirmationService],
})
export class AccountListComponent implements OnInit {
  accounts: any[] = [];
  loading = false;

  // Pagination
  first = 0;
  rows = 10;
  totalRecords = 0;

  constructor(
    private accountService: AdminAccountService,
    private router: Router,
    private messageService: MessageService,
    private confirmationService: ConfirmationService
  ) {}

  ngOnInit(): void {
    this.loadAccounts();
  }

  loadAccounts() {
    this.loading = true;
    this.accountService.apiAdminAccountGet().subscribe({
      next: (response: any) => {
        this.accounts = response.data;
        this.totalRecords = response.data.length;
        this.loading = false;
      },
      error: () => {
        this.messageService.add({
          severity: 'error',
          summary: 'Error',
          detail: 'Failed to load accounts',
        });
        this.loading = false;
      },
    });
  }

  onPageChange(event: any) {
    this.first = event.first;
    this.rows = event.rows;
  }

  confirmDelete(account: any) {
    this.confirmationService.confirm({
      message: `確定要刪除 ${account.name} 的帳戶嗎？`,
      header: '確認刪除',
      icon: 'pi pi-exclamation-triangle',
      accept: () => {
        this.accountService.apiAdminAccountIdDelete(account._id).subscribe({
          next: () => {
            this.messageService.add({
              severity: 'success',
              summary: 'Success',
              detail: '帳戶已刪除',
            });
            this.loadAccounts();
          },
          error: () => {
            this.messageService.add({
              severity: 'error',
              summary: 'Error',
              detail: '刪除帳戶失敗',
            });
          },
        });
      },
    });
  }

  sendTestEmail(account: any) {
    this.loading = true;
    this.accountService
      .apiAdminAccountIdSendTestEmailPost(account._id)
      .subscribe({
        next: () => {
          this.messageService.add({
            severity: 'success',
            summary: 'Success',
            detail: '測試郵件已發送',
          });
          this.loading = false;
        },
        error: () => {
          this.messageService.add({
            severity: 'error',
            summary: 'Error',
            detail: '發送測試郵件失敗',
          });
          this.loading = false;
        },
      });
  }
}
